        // The swaps repeat in a cycle of 6.
        // Let's trace the position of the ball for 6 steps starting from each position.
        // Actually, it's easier to just reverse the process or simulate the cycle.
        // Since n can be up to 2*10^9, we use modulo 6.

        int r = (int)(n % 6);

        // We need to find the initial position such that after r steps, it ends up at x.
        // Let's define the forward moves:
        // Move 1 (odd): swap 0 and 1
        // Move 2 (even): swap 1 and 2
        // Move 3 (odd): swap 0 and 1
        // Move 4 (even): swap 1 and 2
        // Move 5 (odd): swap 0 and 1
        // Move 6 (even): swap 1 and 2

        // Let's simulate the forward moves for a single cycle (6 steps) for each starting position 0, 1, 2.
        // Then we can map the final position after r steps to the initial position.

        // Alternatively, we can just reverse the r steps from x.
        // Reverse of move i:
        // If i is odd, it was a swap of 0 and 1. So reverse is also swap 0 and 1.
        // If i is even, it was a swap of 1 and 2. So reverse is also swap 1 and 2.

        int pos = x;
        for (int i = r; i >= 1; i--) {
            if (i % 2 == 1) {
                // Swap 0 and 1
                if (pos == 0) pos = 1;
                else if (pos == 1) pos = 0;
            } else {
                // Swap 1 and 2
                if (pos == 1) pos = 2;
                else if (pos == 2) pos = 1;
            }
        }

        System.out.println(pos);
    }
