        // Let me re-check.

        // Starting at 0:
        // Move 1 (odd): swap 0,1. Ball at 0 moves to 1.
        // Move 2 (even): swap 1,2. Ball at 1 moves to 2.
        // Move 3 (odd): swap 0,1. Ball at 2 stays at 2.
        // Move 4 (even): swap 1,2. Ball at 2 moves to 1.
        // Move 5 (odd): swap 0,1. Ball at 1 moves to 0.
        // Move 6 (even): swap 1,2. Ball at 0 stays at 0.
        // So 0 -> 0. Correct.

        // Starting at 1:
        // Move 1 (odd): swap 0,1. Ball at 1 moves to 0.
        // Move 2 (even): swap 1,2. Ball at 0 stays at 0.
        // Move 3 (odd): swap 0,1. Ball at 0 moves to 1.
        // Move 4 (even): swap 1,2. Ball at 1 moves to 2.
        // Move 5 (odd): swap 0,1. Ball at 2 stays at 2.
        // Move 6 (even): swap 1,2. Ball at 2 moves to 1.
        // So 1 -> 1. Correct.

        // Starting at 2:
        // Move 1 (odd): swap 0,1. Ball at 2 stays at 2.
        // Move 2 (even): swap 1,2. Ball at 2 moves to 1.
        // Move 3 (odd): swap 0,1. Ball at 1 moves to 0.
        // Move 4 (even): swap 1,2. Ball at 0 stays at 0.
        // Move 5 (odd): swap 0,1. Ball at 0 moves to 1.
        // Move 6 (even): swap 1,2. Ball at 1 moves to 2.
        // So 2 -> 2. Correct.

        // So the permutation after 6 moves is the identity. This means the position after n moves depends only on n % 6.

        // Let's create a table for n % 6 = 0, 1, 2, 3, 4, 5.
        // For each remainder r, we know the final position for each initial position.
        // We need to invert this: given final position x, find initial position.

        // Let's build the mapping from initial to final for r = 0 to 5.
        // r = 0 (n % 6 == 0): 0->0, 1->1, 2->2
        // r = 1 (n % 6 == 1): 
        //   Start 0: move 1 -> 1
        //   Start 1: move 1 -> 0
        //   Start 2: move 1 -> 2
        //   So 0->1, 1->0, 2->2
        // r = 2 (n % 6 == 2):
        //   Start 0: move 1->1, move 2->2 => 0->2
        //   Start 1: move 1->0, move 2->0 => 1->0
        //   Start 2: move 1->2, move 2->1 => 2->1
        //   So 0->2, 1->0, 2->1
        // r = 3 (n % 6 == 3):
        //   Start 0: 0->1->2->2 => 0->2
        //   Start 1: 1->0->0->1 => 1->1
        //   Start 2: 2->2->1->0 => 2->0
        //   So 0->2, 1->1, 2->0
        // r = 4 (n % 6 == 4):
        //   Start 0: 0->1->2->2->1 => 0->1
        //   Start 1: 1->0->0->1->2 => 1->2
        //   Start 2: 2->2->1->0->0 => 2->0
        //   So 0->1, 1->2, 2->0
        // r = 5 (n % 6 == 5):
        //   Start 0: 0->1->2->2->1->0 => 0->0
        //   Start 1: 1->0->0->1->2->2 => 1->2
        //   Start 2: 2->2->1->0->0->1 => 2->1
        //   So 0->0, 1->2, 2->1

        // Now we need to invert these mappings.
        // For a given r and final position x, find initial position.

        int r = (int)(n % 6);

        // mapping[r][initial] = final
        // We want to find initial such that mapping[r][initial] = x

        // Let's create the inverse mapping.
        // For each r, we have a permutation. We can just check which initial position maps to x.

        int result;
        switch (r) {
            case 0:
                // 0->0, 1->1, 2->2
                result = x;
                break;
            case 1:
                // 0->1, 1->0, 2->2
                if (x == 0) result = 1;
                else if (x == 1) result = 0;
                else result = 2;
                break;
            case 2:
                // 0->2, 1->0, 2->1
                if (x == 0) result = 1;
                else if (x == 1) result = 2;
                else result = 0;
                break;
            case 3:
                // 0->2, 1->1, 2->0
                if (x == 0) result = 2;
                else if (x == 1) result = 1;
                else result = 0;
                break;
            case 4:
                // 0->1, 1->2, 2->0
                if (x == 0) result = 2;
                else if (x == 1) result = 0;
                else result = 1;
                break;
            case 5:
                // 0->0, 1->2, 2->1
                if (x == 0) result = 0;
                else if (x == 1) result = 2;
                else result = 1;
                break;
            default:
                result = x;
                break;
        }

        System.out.println(result);
    }
